'use strict';
const $=id=>document.getElementById(id);
const colors={PROCESSING:'#2dd4bf',SETUP:'#a78bfa',LOADING:'#38bdf8',UNLOADING:'#38bdf8',CYCLE_CHANGE:'#38bdf8',IDLE_AVAILABLE:'#4b6078',OFF_SHIFT:'#64748b',ON_BREAK:'#c084fc',CARRYING:'#fbbf24',WALKING:'#60a5fa',IDLE_AT_LOCATION:'#60a5fa'};
const labels={PROCESSING:'בעיבוד',SETUP:'הכנה',LOADING:'טעינה',UNLOADING:'פריקה',CYCLE_CHANGE:'החלפת מחזור',IDLE_AVAILABLE:'פנויה',OFF_SHIFT:'מחוץ למשמרת',ON_BREAK:'בהפסקה',CARRYING:'נושא חלקים',WALKING:'בהליכה',IDLE_AT_LOCATION:'פנוי',WAITING_FOR_WORKER_LOAD:'ממתינה לטעינה',WAITING_FOR_CYCLE_CHANGE:'ממתינה להחלפה',WAITING_FOR_WORKER_UNLOAD:'ממתינה לפריקה'};
let connected=false,result=null,surfaceData=null,currentTab='machines',selected=null,time=0,playing=false,lastFrame=0,taskId=null,yaw=.68;
let machineLayout=[],tracks=new Map(),nodeCoords=[],hitboxes=[],surfaceHits=[],heatHits=[];
const format=(n,d=1)=>n===null||n===undefined||!Number.isFinite(n)?'—':n.toLocaleString('he-IL',{maximumFractionDigits:d});
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notice(text,error=false){$('notice').textContent=text;$('notice').classList.toggle('error',error)}
async function api(path,body){const response=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});if(!response.ok){let message='שגיאת שרת';try{message=(await response.json()).message}catch{}throw Error(message)}return response.json()}
function config(){return{algorithm:$('algorithm').value,arrival_load:+$('arrivalLoad').value,batch_size:+$('batchSize').value,horizon_days:+$('horizon').value,seed:+$('seed').value,trace_days:7,warmup_days:+$('warmup').value}}
function busy(value){document.body.classList.toggle('busy',value);for(const id of ['run','scenario','grid'])$(id).disabled=value||!connected;$('cancel').hidden=!value}
async function run(mode){if(!connected){notice('הפעל את run_factory.py במחשב, או טען קובץ תוצאה שמור.',true);return}busy(true);$('progress').textContent='מתחיל הרצה…';try{const data=await api('/api/run',{mode,config:config()});taskId=data.id;await poll()}catch(e){notice(e.message,true);busy(false)}}
async function poll(){const task=await api('/api/tasks/'+taskId);$('progress').textContent=task.message;if(task.status==='RUNNING'){setTimeout(()=>poll().catch(e=>{notice(e.message,true);busy(false)}),900);return}busy(false);if(task.status==='COMPLETE'){if(task.result.trace)loadRun(task.result);else loadSurface(task.result);$('progress').textContent='ההרצה הסתיימה ונשמרה.'}else notice(task.message,true)}
function loadRun(data){surfaceData=null;renderSurfaces();if(!data||!Array.isArray(data.machines)||!data.trace||!Array.isArray(data.trace.intervals)||!Array.isArray(data.jobs))throw Error('קובץ תוצאה אינו תואם למנוע הייצור');result=data;$('warmup').value=data.config.warmup_days;$('seed').value=data.config.seed;$('algorithm').value=data.config.algorithm;machineLayout=data.machines;nodeCoords=data.trace.nodes;tracks=new Map();for(const interval of data.trace.intervals){if(!tracks.has(interval.entity))tracks.set(interval.entity,[]);tracks.get(interval.entity).push(interval)}for(const list of tracks.values())list.sort((a,b)=>a.start-b.start);time=data.trace.start_min||0;playing=false;selected=null;$('scrub').min=time;$('seek').min=time;$('flow').textContent=format(data.mean_flow_min===null?null:data.mean_flow_min/60);$('complete').textContent=format(data.completed_measurement_jobs,0);$('cohort').textContent='מתוך '+format(data.measurement_jobs,0)+' עבודות ששוחררו בחלון';$('utilization').textContent=format(data.machine_utilization*100)+'%';$('wip').textContent=format(data.mean_wip);$('machineCount').textContent=machineLayout.length+' מכונות';$('scrub').max=data.trace.end_min;$('seek').max=data.trace.end_min;$('scrub').disabled=false;$('play').disabled=false;$('next').disabled=false;$('download').disabled=false;$('play').textContent='▶ הפעל שחזור';$('empty').style.display='none';$('replayLimit').textContent='שחזור מיום '+format((data.trace.start_min||0)/1440)+' עד יום '+format(data.trace.end_min/1440);$('provenance').textContent='World '+data.world_version+' · Python '+data.environment.python+' · Seed '+data.config.seed+' · Dataset '+data.dataset_sha256.slice(0,12);$('loadMetrics').textContent='Available machine utilization: '+format((data.machine_available_utilization??data.machine_utilization)*100)+'% · מכונות זמינות לעיבוד אוטונומי 24/7 · Bottleneck '+format(data.bottleneck_utilization*100)+'% · Worker available '+format(data.worker_available_utilization*100)+'% · Mean queue '+format(data.mean_queue)+' · Throughput '+format(data.throughput_jobs_per_day)+' עבודות/יום · Baseline factor '+format(data.demand_provenance?.baseline_calibration_multiplier,4)+' · Effective arrivals '+format(data.demand_provenance?.effective_arrival_rate,3)+'/יום';const drift=data.operating_point?.candidates?.[String(data.config.baseline_calibration_multiplier)]?.wip_slope_ci95_across_replications;if(drift?.[0]>0)$('loadMetrics').textContent+=' · אזהרה: מגמת WIP חיובית נותרה; יציבות לא הוכחה';notice('ריצה בודדת · '+data.status+' · זמן השהייה כולל ניקוז; ניצולת, תורים ותפוקה נמדדים בחלון בלבד. השחזור מוגבל לחלון המוצג.');drawFloor();renderEntities();updateClock()}
function intervalAt(id,t=time){const list=tracks.get(id)||[];let l=0,r=list.length-1,found=null;while(l<=r){const m=(l+r)>>1;if(list[m].start<=t){found=list[m];l=m+1}else r=m-1}return found&&t<=found.end?found:null}
function position(interval){if(!interval)return null;if(interval.path?.length){const points=interval.path.map(i=>nodeCoords[i]);let total=0;for(let i=1;i<points.length;i++)total+=Math.abs(points[i][0]-points[i-1][0])+Math.abs(points[i][1]-points[i-1][1]);let remaining=Math.max(0,Math.min(1,(time-interval.start)/((interval.move_end??interval.end)-interval.start||1)))*total;for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],d=Math.abs(b[0]-a[0])+Math.abs(b[1]-a[1]);if(remaining<=d){const f=d?remaining/d:0;return[a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f]}remaining-=d}return points.at(-1)}return nodeCoords[interval.node]||null}
function transform(){const xs=machineLayout.map(m=>m.x+m.w),ys=machineLayout.map(m=>m.y+m.h);const maxX=Math.max(1,...xs),maxY=Math.max(1,...ys);const canvas=$('floor');const scale=1400/maxX;const wanted=Math.round(maxY*scale+110);if(canvas.height!==wanted)canvas.height=wanted;return {scale,x:50,y:70}}
function drawFloor(){const canvas=$('floor'),tr=transform(),ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#0b1624';ctx.fillRect(0,0,canvas.width,canvas.height);const xy=p=>[tr.x+p[0]*tr.scale,tr.y+p[1]*tr.scale];ctx.strokeStyle='#14273b';ctx.lineWidth=1;for(let x=20;x<1500;x+=40){ctx.beginPath();ctx.moveTo(x,20);ctx.lineTo(x,canvas.height-20);ctx.stroke()}for(let y=20;y<canvas.height;y+=40){ctx.beginPath();ctx.moveTo(20,y);ctx.lineTo(1480,y);ctx.stroke()}ctx.font='18px Segoe UI';ctx.fillStyle='#7e96af';ctx.textAlign='center';ctx.fillText('MILLING / כרסום',360,38);ctx.fillText('TURNING / חריטה',1110,38);const border=xy([1150,0])[0];ctx.setLineDash([6,8]);ctx.strokeStyle='#365069';ctx.beginPath();ctx.moveTo(border,55);ctx.lineTo(border,canvas.height-20);ctx.stroke();ctx.setLineDash([]);hitboxes=[];for(const m of machineLayout){const [x,y]=xy([m.x,m.y]),w=m.w*tr.scale,h=m.h*tr.scale;const state=intervalAt(m.id)?.state||'IDLE_AVAILABLE',color=colors[state]||'#fbbf24';ctx.fillStyle=color+'22';ctx.strokeStyle=selected?.id===m.id?'#fff':color;ctx.lineWidth=selected?.id===m.id?3:1.3;ctx.beginPath();ctx.roundRect(x,y,w,h,4);ctx.fill();ctx.stroke();ctx.fillStyle=color;ctx.fillRect(x+5,y+6,4,Math.max(4,h-12));ctx.fillStyle='#dce9f7';ctx.font='18px Consolas,monospace';ctx.textAlign='center';ctx.fillText(m.id,x+w/2,y+h/2+5);hitboxes.push({x,y,w,h,type:'machines',id:m.id})}if(result){const occupied=new Map();for(const w of result.workers){const interval=intervalAt(w.id);if(!interval||interval.state==='OFF_SHIFT')continue;const pos=position(interval);if(!pos)continue;let [x,y]=xy(pos);const place=Math.round(x)+','+Math.round(y),slot=occupied.get(place)||0;occupied.set(place,slot+1);if(slot){const angle=slot*2.39996,radius=13*Math.ceil(slot/6);const ox=x,oy=y;x+=Math.cos(angle)*radius;y+=Math.sin(angle)*radius;ctx.strokeStyle='#60a5fa70';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(ox,oy);ctx.lineTo(x,y);ctx.stroke()}if(interval.path&&selected?.id===w.id){ctx.strokeStyle='#60a5fa80';ctx.lineWidth=3;ctx.beginPath();interval.path.forEach((n,i)=>{const p=xy(nodeCoords[n]);i?ctx.lineTo(...p):ctx.moveTo(...p)});ctx.stroke()}ctx.fillStyle=colors[interval.state]||'#60a5fa';ctx.strokeStyle='#091523';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,7,0,Math.PI*2);ctx.fill();ctx.stroke();if(selected?.id===w.id){ctx.strokeStyle='#fff';ctx.beginPath();ctx.arc(x,y,11,0,Math.PI*2);ctx.stroke()}hitboxes.push({x:x-10,y:y-10,w:20,h:20,type:'workers',id:w.id})}}const p=xy([1150,200]);ctx.fillStyle='#9dafc6';ctx.font='12px Segoe UI';ctx.fillText('HANDOFF',p[0],p[1]-15)}
function jobState(j){if(time<j.release)return'טרם שוחררה';if(j.complete!==null&&time>=j.complete)return'הושלמה';return'בתהליך'}
function batchState(b){if(time<b.ready)return'טרם הגיעה';const initial=result.trace.initial?.batches?.[b.id];if(initial?.state==='COMPLETE')return'הושלמה';if(initial?.state==='SPLIT')return'פוצלה';const active=[...tracks.keys()].map(id=>intervalAt(id)).find(i=>i?.batch===b.id);if(active)return labels[active.state]||active.state;const events=(result?.trace.events||[]).filter(e=>e.batch===b.id&&e.time<=time);if(events.some(e=>e.kind==='split'))return'פוצלה';if(events.filter(e=>e.kind==='parts_unloaded').reduce((n,e)=>n+e.hi-e.lo,initial?.completed||0)>=b.hi-b.lo)return'הושלמה';return'ממתינה';}
function renderEntities(){const q=$('search').value.toLowerCase();const list=result?result[currentTab]:currentTab==='machines'?machineLayout:[];const shown=(list||[]).filter(e=>String(e.id).toLowerCase().includes(q));$('entities').innerHTML=shown.map(e=>{const state=currentTab==='jobs'?jobState(e):currentTab==='batches'?batchState(e):labels[intervalAt(e.id)?.state]||(currentTab==='workers'?'מחוץ למשמרת':'פנויה');const id=String(e.id);return`<button class="entity ${selected?.id===id?'selected':''}" data-id="${escape(id)}"><b dir="ltr">${escape(currentTab==='workers'?id.split('_').slice(-1)[0].slice(0,8):['jobs','batches'].includes(currentTab)?id.slice(-18):id)}</b><span>${escape(state)}</span></button>`}).join('');for(const button of $('entities').querySelectorAll('button'))button.onclick=()=>select(currentTab,button.dataset.id);renderInspector()}
function select(type,id){selected={type,id};currentTab=type;for(const b of document.querySelectorAll('[data-tab]'))b.setAttribute('aria-selected',String(b.dataset.tab===type));renderEntities();drawFloor()}
function renderInspector(){if(!selected)return;const row=(result?.[selected.type]||machineLayout).find(x=>x.id===selected.id);if(!row)return;const interval=intervalAt(row.id);let lines=[];if(selected.type==='machines'){lines=[['מחלקה',row.department==='milling'?'כרסום':'חריטה'],['מצב',labels[interval?.state]||'פנויה'],['עבודה',interval?.job||'—'],['תת־מנה',interval?.batch||'—'],['עובד מטפל',interval?.worker||'—']]}else if(selected.type==='workers'){lines=[['מחלקה',row.department==='milling'?'כרסום':'חריטה'],['מצב',labels[interval?.state]||'מחוץ למשמרת'],['משמרת',row.kind==='day'?'יום':'לילה'],['מכונה',interval?.machine||'—'],['תת־מנה',interval?.batch||'—'],['כשירויות',row.skills.join(', ')]]}else if(selected.type==='batches'){lines=[['מצב בשחזור',batchState(row)],['עבודת מקור',row.job],['כמות',row.hi-row.lo],['מזהי חלקים',row.lo+'–'+(row.hi-1)],['פעולה',result.jobs.find(j=>j.id===row.job)?.route[row.op_index]],['מנה מקורית',row.parent||'מנה ראשית'],['מכונת יעד',row.target||'לפי ההקצאה']]}else{const unloaded=(result.trace.events||[]).filter(e=>e.kind==='parts_unloaded'&&e.job===row.id&&e.time<=time&&e.operation===row.route.at(-1)).reduce((n,e)=>n+e.hi-e.lo,0);const prior=result.trace.initial?.job_completed?.[row.id]||0;lines=[['מצב',jobState(row)],['פריט',row.item],['כמות מקורית',row.quantity],['הושלמו בשחזור',prior+unloaded],['ניתוב',row.route.join(' → ')],['שחרור',format(row.release/60)+' שעות'],['זמן שהייה בסוף הריצה המלאה',row.complete!==null?format((row.complete-row.release)/60)+' שעות':'—']];const batches=(result.batches||[]).filter(b=>b.job===row.id&&b.ready<=time);lines.push(['תתי־מנות שנוצרו עד כאן',batches.length]);lines.push(['תת־מנה אחרונה',batches.at(-1)?.id||'—'])}$('inspector').innerHTML='<h3 dir="ltr">'+escape(row.id)+'</h3>'+lines.map(([k,v])=>`<p>${escape(k)}: <b>${escape(v)}</b></p>`).join('')}
function updateClock(){if(result){const released=result.jobs.filter(j=>j.release<=time).length,completed=result.jobs.filter(j=>j.complete!==null&&j.complete<=time).length;let snapshot=null;for(const x of result.trace.snapshots||[]){if(x.time>time)break;snapshot=x}$('liveCounts').textContent='בזמן השחזור · Released '+released+' · Completed '+completed+' · Current WIP '+(released-completed)+' · Queued batches / requests '+(snapshot?.queue??'—');}if(!result)return;const start=new Date(result.config.start_date+'Z');const date=new Date(start.getTime()+time*60000);$('clock').textContent=date.toISOString().slice(0,16).replace('T',' · ');$('scrub').value=time;if(document.activeElement!==$('seek'))$('seek').value=time.toFixed(2)}
function frame(stamp){const dt=lastFrame?(stamp-lastFrame)/1000:0;lastFrame=stamp;if(playing&&result){time=Math.min(result.trace.end_min,time+dt*(+$('speed').value)/60);if(time>=result.trace.end_min){playing=false;$('play').textContent='▶ הפעל שחזור'}drawFloor();updateClock();if(Math.floor(stamp/400)!==Math.floor((stamp-dt*1000)/400))renderEntities()}requestAnimationFrame(frame)}
function loadSurface(data){surfaceData=data.points?data:{points:[data],grid:[data.arrival_load],purpose:data.purpose};if(!Array.isArray(surfaceData.points))throw Error('Invalid experiment file');$('download').disabled=false;renderSurfaces();notice(data.purpose?'נתוני בדיקת קבלה מבוקרת — אינם אומדן של רצפת הייצור.':'תוצאות מחקר נטענו. מצב אי־התייצבות או אי־עמידה בדיוק מסומן לכל נקודה בנפרד.')}
function cellValue(p){const algo=$('surfaceAlgorithm').value,summary=p.algorithms?.[algo],base=p.algorithms?.FIFO;if(!summary||summary.mean===null||summary.mean===undefined)return null;const mode=$('view').value;if(mode==='delta')return base?.mean!==null&&base?.mean!==undefined?(summary.mean-base.mean)/60:null;if(mode==='improvement')return base?.mean?100*(base.mean-summary.mean)/base.mean:null;return summary.mean/60}
function pointText(p){const s=p.algorithms?.[$('surfaceAlgorithm').value]||{};return `a=${p.arrival_load} · b=${p.batch_size} · n=${s.n||0} · CI95% ${s.ci95?s.ci95.map(x=>format(x/60)).join(' – '):'—'} שעות · חימום ${p.warmup_days??'—'} ימים · ${p.status} · seed=${p.seed} · ${p.world_version} · dataset=${p.dataset_sha256?.slice(0,12)}`}
function renderSurfaces(){drawSurface();drawHeatmap();const points=surfaceData?.points||[];$('resultsTable').innerHTML=points.flatMap(p=>Object.entries(p.algorithms||{}).map(([a,s])=>`<tr><td>${p.arrival_load}</td><td>${p.batch_size}</td><td>${escape(a)}</td><td>${format(s.mean===null?null:s.mean/60)}</td><td dir="ltr">${s.ci95?s.ci95.map(x=>format(x/60)).join(' – '):'—'}</td><td>${s.n||0}</td><td>${p.warmup_days??'—'}</td><td class="${p.status!=='PRECISION_MET'?'warning':''}">${escape(s.status||p.status)}</td></tr>`)).join('');if(points.length)$('pointDetails').textContent=pointText(points[0]);else $('pointDetails').textContent='תוצאות יופיעו לאחר הניסוי. אין כרגע משטח מחקר מחושב.'}
function color(v,min,max){const f=(v-min)/(max-min||1);return`hsl(${175-140*f} 70% 55%)`}
function drawSurface(){const c=$('surface'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);surfaceHits=[];const pts=surfaceData?.points||[];const values=pts.map(cellValue).filter(x=>x!==null),min=Math.min(0,...values),max=Math.max(1,...values);const maxA=Math.max(1.5,...pts.map(p=>p.arrival_load)),maxB=Math.max(1.5,...pts.map(p=>p.batch_size));const project=(a,b,z)=>{const x=a/maxA-.5,y=b/maxB-.5;return[400+(x*Math.cos(yaw)-y*Math.sin(yaw))*430,290+(x*Math.sin(yaw)+y*Math.cos(yaw))*110-(z-min)/(max-min)*180]};ctx.lineWidth=1;ctx.strokeStyle='#36516d';ctx.font='14px Segoe UI';ctx.textAlign='center';const origin=project(0,0,min);for(const [p,label]of[[project(maxA,0,min),'Arrival load ×'],[project(0,maxB,min),'Batch size ×'],[project(0,0,max),'Flow time / Δ / %']]){ctx.beginPath();ctx.moveTo(...origin);ctx.lineTo(...p);ctx.stroke();ctx.fillStyle='#b5c8de';ctx.fillText(label,p[0],p[1]+(label.includes('Flow')?-16:24))}const grid=Array.from(new Set(pts.map(p=>p.arrival_load))).sort((a,b)=>a-b),by=new Map(pts.map(p=>[`${p.arrival_load},${p.batch_size}`,p]));for(let i=0;i<grid.length-1;i++)for(let j=0;j<grid.length-1;j++){const corners=[[grid[i],grid[j]],[grid[i+1],grid[j]],[grid[i+1],grid[j+1]],[grid[i],grid[j+1]]].map(([a,b])=>by.get(`${a},${b}`));if(corners.every(p=>p&&p.status==='PRECISION_MET'&&cellValue(p)!==null)){ctx.fillStyle=color(corners.reduce((s,p)=>s+cellValue(p),0)/4,min,max).replace('hsl','hsla').replace('%)','% / .25)');ctx.strokeStyle='#39726c';ctx.beginPath();corners.forEach((p,k)=>{const pos=project(p.arrival_load,p.batch_size,cellValue(p));k?ctx.lineTo(...pos):ctx.moveTo(...pos)});ctx.closePath();ctx.fill();ctx.stroke()}}for(const p of pts){const v=cellValue(p),pos=project(p.arrival_load,p.batch_size,v??min);ctx.fillStyle=v===null?'#fbbf24':color(v,min,max);ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=2;if(v===null){ctx.beginPath();ctx.moveTo(pos[0]-5,pos[1]-5);ctx.lineTo(pos[0]+5,pos[1]+5);ctx.moveTo(pos[0]+5,pos[1]-5);ctx.lineTo(pos[0]-5,pos[1]+5);ctx.stroke()}else{ctx.beginPath();if(p.status==='PRECISION_NOT_MET'){ctx.moveTo(pos[0],pos[1]-6);ctx.lineTo(pos[0]+6,pos[1]);ctx.lineTo(pos[0],pos[1]+6);ctx.lineTo(pos[0]-6,pos[1]);ctx.closePath();ctx.stroke()}else{ctx.arc(...pos,5,0,Math.PI*2);ctx.fill()}}surfaceHits.push({x:pos[0]-10,y:pos[1]-10,w:20,h:20,p})}ctx.fillStyle='#9aafc8';ctx.fillText(pts.length?'בחירת נקודה מציגה דיוק, חימום ומקור':'הפעל ניסוי או טען תוצאת מחקר',400,410)}
function drawHeatmap(){const c=$('heatmap'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);heatHits=[];const pts=surfaceData?.points||[];const ax=Array.from(new Set(pts.map(p=>p.arrival_load))).sort((a,b)=>a-b),by=Array.from(new Set(pts.map(p=>p.batch_size))).sort((a,b)=>a-b);const vals=pts.map(cellValue).filter(v=>v!==null),min=Math.min(0,...vals),max=Math.max(1,...vals);ctx.font='14px Segoe UI';ctx.textAlign='center';ctx.fillStyle='#b5c8de';ctx.fillText('Arrival load ×',345,425);ctx.save();ctx.translate(23,220);ctx.rotate(-Math.PI/2);ctx.fillText('Batch size ×',0,0);ctx.restore();if(!pts.length){ctx.fillText('אותם נתונים, מבט נוסף',325,220);return}const width=510/ax.length,height=315/by.length;for(const p of pts){const x=85+ax.indexOf(p.arrival_load)*width,y=55+(by.length-1-by.indexOf(p.batch_size))*height,v=cellValue(p);ctx.fillStyle=v===null?'#1c2c40':color(v,min,max);ctx.fillRect(x+3,y+3,width-6,height-6);ctx.fillStyle=v===null?'#fbbf24':'#062726';ctx.font='16px Consolas';ctx.fillText(v===null?'×':format(v)+(p.status==='PRECISION_NOT_MET'?' ◇':''),x+width/2,y+height/2+6);heatHits.push({x,y,w:width,h:height,p})}ctx.fillStyle='#b5c8de';ctx.font='14px Consolas';ax.forEach((v,i)=>ctx.fillText(v,85+(i+.5)*width,395));by.forEach((v,i)=>ctx.fillText(v,60,55+(by.length-i-.5)*height+5))}
function hit(canvas,event,boxes){const r=canvas.getBoundingClientRect(),x=(event.clientX-r.left)*canvas.width/r.width,y=(event.clientY-r.top)*canvas.height/r.height;return [...boxes].reverse().find(b=>x>=b.x&&x<=b.x+b.w&&y>=b.y&&y<=b.y+b.h)}
$('floor').onclick=e=>{const h=hit($('floor'),e,hitboxes);if(h)select(h.type,h.id)};
$('surface').onclick=e=>{const h=hit($('surface'),e,surfaceHits);if(h)$('pointDetails').textContent=pointText(h.p)};
$('heatmap').onclick=e=>{const h=hit($('heatmap'),e,heatHits);if(h)$('pointDetails').textContent=pointText(h.p)};
let drag=null;$('surface').onpointerdown=e=>{drag=e.clientX;$('surface').setPointerCapture(e.pointerId)};$('surface').onpointermove=e=>{if(drag!==null){yaw+=(e.clientX-drag)*.007;drag=e.clientX;drawSurface()}};$('surface').onpointerup=()=>{drag=null};
for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{currentTab=b.dataset.tab;selected=null;for(const btn of document.querySelectorAll('[data-tab]'))btn.setAttribute('aria-selected',String(btn===b));$('inspector').innerHTML='<p class="muted">בחר ישות להצגת פרטים.</p>';renderEntities()};
$('zoom').onchange=()=>{$('floor').style.width=(+$('zoom').value*100)+'%'};$('search').oninput=renderEntities;$('arrivalLoad').oninput=()=>$('loadOut').textContent='×'+(+$('arrivalLoad').value).toFixed(2);$('batchSize').oninput=()=>$('batchOut').textContent='×'+(+$('batchSize').value).toFixed(2);
$('run').onclick=()=>run('run');$('scenario').onclick=()=>run('scenario');$('grid').onclick=()=>run('grid');$('cancel').onclick=()=>api('/api/cancel/'+taskId,{}).then(x=>$('progress').textContent=x.message).catch(e=>notice(e.message,true));
$('seek').oninput=()=>{if(result){time=Math.max(result.trace.start_min||0,Math.min(result.trace.end_min,+$('seek').value||0));drawFloor();updateClock();renderEntities()}};$('play').onclick=()=>{if(time>=result.trace.end_min)time=result.trace.start_min||0;playing=!playing;$('play').textContent=playing?'Ⅱ השהה':'▶ הפעל שחזור'};$('scrub').oninput=()=>{time=+$('scrub').value;drawFloor();updateClock();renderEntities()};$('next').onclick=()=>{const next=result.trace.events.find(e=>e.time>time+.00001);if(next){time=next.time;drawFloor();updateClock();renderEntities()}};
$('surfaceAlgorithm').onchange=renderSurfaces;$('view').onchange=renderSurfaces;
$('download').onclick=()=>{const data=surfaceData||result;if(!data)return;const blob=new Blob([JSON.stringify(data)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=surfaceData?'production-experiment.json':'production-run.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('upload').onchange=async()=>{try{const data=JSON.parse(await $('upload').files[0].text());data.trace?loadRun(data):loadSurface(data)}catch(e){notice('טעינת הקובץ נכשלה: '+e.message,true)}};
async function init(){const replay=new URLSearchParams(location.search).get('replay');if(replay){try{const r=await fetch(replay);loadRun(await r.json())}catch(e){notice('טעינת השחזור נכשלה: '+e.message,true)}}drawFloor();renderSurfaces();busy(false);try{const data=await api('/api/config');connected=true;if(data.operating_point?.status==='CALIBRATED')$('warmup').value=data.operating_point.warmup_days;machineLayout=data.machines;$('machineCount').textContent=machineLayout.length+' מכונות';$('connection').textContent='Python מחובר · '+data.templates+' תבניות · '+(data.operating_point?.status==='CALIBRATED'?'בסיס ניסיוני · אישור לאופק מוגבל':'בסיס היסטורי — כיול עומס טרם אושר');$('provenance').textContent='World '+data.world_version+' · Dataset '+data.dataset_sha256.slice(0,16);drawFloor();renderEntities();busy(false)}catch{$('connection').textContent='מצב צפייה בקובץ';notice('להרצה מקומית: python run_factory.py. אפשר לצפות כאן בתוצאת JSON שמורה.');busy(false)}requestAnimationFrame(frame)}
init();
